package cn.local.rainreminder;
import android.Manifest;import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import java.util.*;
public class SettingsActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);show();}
 void permission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},33);}

 void show(){LinearLayout root=Ui.screen(this,"设置");LinearLayout account=Ui.card(this,root);account.addView(Ui.text(this,"作业检查",18));Switch daily=new Switch(this);daily.setTypeface(Ui.font(this));daily.setText("每天自动检查作业");daily.setChecked(Store.prefs(this).getBoolean("enabled",false));daily.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,8));account.addView(daily);daily.setOnCheckedChangeListener((v,on)->{Store.prefs(this).edit().putBoolean("enabled",on).apply();Store.schedule(this);if(on)permission();});int hour=Store.prefs(this).getInt("hour",20),minute=Store.prefs(this).getInt("minute",0);Ui.link(this,account,String.format(Locale.CHINA,"检查时间  %02d:%02d  ›",hour,minute),()->new TimePickerDialog(this,(v,h,m)->{Store.prefs(this).edit().putInt("hour",h).putInt("minute",m).apply();Store.schedule(this);Ui.keepScroll(this,this::show);},hour,minute,true).show());account.addView(Ui.hint(this,"联网且系统允许时检查，省电设置可能延迟。"));
 LinearLayout reminders=Ui.card(this,root);reminders.addView(Ui.text(this,"提醒与桌面",18));Switch live=new Switch(this);live.setTypeface(Ui.font(this));live.setText("老师开课时提醒扫码");live.setChecked(Store.prefs(this).getBoolean("watchOpenClass",true));live.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,10));reminders.addView(live);live.setOnCheckedChangeListener((v,on)->{Store.prefs(this).edit().putBoolean("watchOpenClass",on).apply();ClassWatch.schedule(this);if(on)permission();});LinearLayout detail=Ui.fold(this,reminders,"开课提醒说明");detail.addView(Ui.hint(this,"作业页前台约1分钟检查，后台由系统约15分钟或更久安排，省电可能延迟；无需导入课表。"));Ui.link(this,reminders,"添加桌面小组件  ›",()->RainWidget.pin(this));Ui.link(this,reminders,"通知与后台运行设置  ›",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));Ui.link(this,reminders,"发送测试通知",()->{permission();Store.notify(this,"通知测试","请在系统设置中允许横幅显示。");});
 }
}
